// RFC 9380 §5.3.1 with SHA-256, which is the bottom of the pipeline: get the
// DST' length byte wrong and every scalar above it is wrong in a way no other
// test would localise.
struct XmdVector {
    const char *name;
    const char *dst;
    size_t dst_length;
    const char *msg;
    size_t msg_length;
    size_t out_length;
    uint8_t out[96];
};

